// Parse Agent 3 output
const raw = $input.first().json.choices[0].message.content;
const clean = raw.replace(/```json|```/g, '').trim();
let agent3;
try {
  agent3 = JSON.parse(clean);
} catch(e) {
  agent3 = { immediate_action: 'Manual review required', preventive_measures: [], estimated_recovery: 'Unknown', escalation_needed: true, confidence_score: 0.5 };
}

// Get all previous agent data
const prev = $('Agent 2 Parser').first().json;

// Calculate consensus confidence (average of 3 agents)
const avgConfidence = (
  (prev.agent1_confidence || 0.8) + 
  (prev.agent2_confidence || 0.7) + 
  (agent3.confidence_score || 0.7)
) / 3;
const roundedConf = Math.round(avgConfidence * 100) / 100;

// Take the highest severity (conservative approach)
const maxSeverity = prev.agent1_severity || 'MEDIUM';

// === ESCALATION LOGIC (Confidence-Based Guardrails) ===
let escalation_level, escalation_emoji;
if (roundedConf >= 0.85) {
  escalation_level = 'AUTONOMOUS';
  escalation_emoji = '🤖';
} else if (roundedConf >= 0.50) {
  escalation_level = 'HUMAN_REVIEW';
  escalation_emoji = '👤';
} else {
  escalation_level = 'ESCALATED';
  escalation_emoji = '🚨';
}

return [{
  json: {
    method: 'MULTI_AGENT_LLM',
    anomaly_detected: prev.agent1_anomaly_detected,
    anomaly_type: prev.agent1_anomaly_type,
    severity: maxSeverity,
    affected_node: prev.node_id,

    // Agent 1 — Detector
    explanation: prev.agent1_diagnosis,

    // Agent 2 — Root Cause
    root_cause: prev.agent2_root_cause,
    impact_scope: prev.agent2_impact_scope,

    // Agent 3 — Action
    suggested_action: agent3.immediate_action,
    preventive_measures: (agent3.preventive_measures || []).join('; '),
    estimated_recovery: agent3.estimated_recovery,
    escalation_needed: agent3.escalation_needed,

    // Consensus + Escalation
    consensus_confidence: roundedConf,
    escalation_level: escalation_level,
    escalation_emoji: escalation_emoji,
    agents_completed: '3/3',

    // Original data
    message: prev.message,
    health_score: prev.health_score,
    network_summary: prev.network_summary
  }
}];

// === SELF-HEALING ENGINE ===
// Simulates autonomous recovery actions based on escalation level
const data = $input.first().json;

const HEALING_ACTIONS = {
  NODE_FAILURE: [
    { action: 'Initiating soft restart', detail: 'Sending RST signal via RPL control plane', eta: '~2 min' },
    { action: 'Rerouting traffic', detail: 'Updating RPL DODAG, redirecting via backup parent', eta: '~30 sec' }
  ],
  ROUTING_FAILURE: [
    { action: 'Re-probing route', detail: 'Sending DIO/DIS messages to verify reachability', eta: '~45 sec' },
    { action: 'Triggering local repair', detail: 'RPL local repair procedure initiated', eta: '~1 min' }
  ],
  TOPOLOGY_CHANGE: [
    { action: 'Logging topology change', detail: 'Recording parent switch for trend analysis', eta: 'Monitoring' }
  ]
};

const actions = HEALING_ACTIONS[data.anomaly_type] || HEALING_ACTIONS.TOPOLOGY_CHANGE;
const selected = actions[Math.floor(Math.random() * actions.length)];

let healing_status;
if (data.escalation_level === 'AUTONOMOUS') {
  healing_status = '✅ ACTION EXECUTED';
} else if (data.escalation_level === 'HUMAN_REVIEW') {
  healing_status = '⏳ PENDING HUMAN APPROVAL';
} else {
  healing_status = '🚨 ESCALATED TO SENIOR ENGINEER';
}

return [{
  json: {
    ...data,
    // Self-Healing fields
    healing_action: selected.action,
    healing_detail: selected.detail,
    healing_eta: selected.eta,
    healing_status: healing_status,
    healing_auto_executed: data.escalation_level === 'AUTONOMOUS'
  }
}];

